import java.util.*;
public class CF1342E {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        long k = scanner.nextLong();
        final int MOD = 998244353;
        if (k >= n) {
            System.out.println(0);
            return;
        }
        int c = n - (int) k;
        long[] factorials = new long[2 * n];
        long[] invFactorials = new long[2 * n];
        factorials[0] = 1;
        for (int i = 1; i < 2 * n; i++) {
            factorials[i] = (factorials[i - 1] * i) % MOD;
        }
        invFactorials[2 * n - 1] = modInverse(factorials[2 * n - 1], MOD);
        for (int i = 2 * n - 2; i >= 0; i--) {
            invFactorials[i] = (invFactorials[i + 1] * (i + 1)) % MOD;
        }
        long totalSum = 0;
        for (int a = 1; a <= c; a++) {
            long val = (power(a, n, MOD) * nCr(c, a, factorials, invFactorials, MOD)) % MOD;
            totalSum += (a % 2 == 0 ? 1 : -1) * val;
        }
        totalSum = ((totalSum % MOD) + MOD) % MOD;
        totalSum = (totalSum * nCr(n, c, factorials, invFactorials, MOD)) % MOD;
        if (k > 0) totalSum = (totalSum * 2) % MOD;
        System.out.println(totalSum);
    }

    static long power(long base, int exp, int mod) {
        long res = 1;
        long cur = base % mod;
        while (exp > 0) {
            if ((exp & 1) == 1) res = (res * cur) % mod;
            cur = (cur * cur) % mod;
            exp >>= 1;
        }
        return res;
    }

    static long nCr(int n, int r, long[] fact, long[] invFact, int mod) {
        return fact[n] * invFact[r] % mod * invFact[n - r] % mod;
    }

    static long modInverse(long a, int m) {
        return power(a, m - 2, m);
    }
}
